public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Checks whether a gift with next_send_date in the future can be sent already
    /// </summary>
    public Task<TdLib.TdApi.Objects.CanSendGiftResult> CanSendGiftAsync(long giftId = default)
    {

           using var activity =  StartCallActivity("CanSendGiftAsync", typeof(CanSendGift).FullName ?? "CanSendGiftAsync");

           try
           {
             return client.CanSendGiftAsync(giftId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
